pub fn qualify_batch4(c:&SpriteActionCatalog)->Result<Vec<(u32,u8,Animation)>,HonorAssetError> {qualify_specs(c,BATCH4_SPECS)}
pub fn qualify(c:&SpriteActionCatalog)->Result<Vec<(u32,u8,Animation)>,HonorAssetError> {qualify_specs(c,SPECS)}
fn qualify_specs(c:&SpriteActionCatalog,specs:&[Spec])->Result<Vec<(u32,u8,Animation)>,HonorAssetError> {
    let mut result=Vec::new();
    for spec in specs {
        let row=c.sprites.get(&spec.sprite).ok_or(HonorAssetError::Unsupported("additional finite effect absent"))?;
        if row.id!=spec.sprite || row.graphics_id!=spec.bank || row.image_count!=Some(1)
            || row.header_issue.is_some() || row.header_bytes!=spec.header || row.actions.len()!=1
            || row.attributes.len()!=spec.attrs.len()
            || row.attributes.iter().zip(spec.attrs).any(|(actual,(key,body))|actual.key!=ActionKey::new(*key)||actual.body_bytes!=*body) {
            return Err(HonorAssetError::Unsupported("additional finite effect definition changed"));
        }
        let resolved=c.resolve_action(spec.sprite,ActionKey::new(0))?;
        let a=resolved.animation;
        if resolved.definition_sprite_id!=spec.sprite || a.directionality!=Directionality::Undirected
            || a.frames_per_second!=24 || a.frames.len()!=spec.frames.len()
            || a.frames.iter().zip(spec.frames).any(|(actual,(image,subframe,ticks,sounds))|
                (actual.image_id,actual.subframe,actual.duration_ticks)!=(*image,*subframe,*ticks)
                || actual.events!=sounds.iter().map(|sound|FrameEvent::Sound(*sound)).collect::<Vec<_>>()) {
            return Err(HonorAssetError::Unsupported("additional finite effect timing changed"));
        }
        result.push((spec.sprite,0,a.clone()));
    }
    Ok(result)
}


// Original2251 has one no-block slot. It retains the normal clip/audio clock.
const ORIGINAL2251_SHA:[u8;32]=[185,12,69,1,70,41,110,119,4,48,144,148,139,17,7,92,7,49,252,123,21,9,55,52,220,55,147,90,17,77,151,91];
pub fn requires_reviewed_blank(name:&str)->bool{name=="2251-0.spr"}
pub fn is_reviewed_blank(name:&str,index:usize,f:&super::sprite::SpriteFrame)->bool{
    requires_reviewed_blank(name)&&index==0
        &&(f.x_offset,f.y_offset,f.width,f.height,f.frame_type,f.unknown1,f.unknown2)==(192,120,0,0,0,u16::MAX,0)
        &&f.rgba.is_empty()&&f.fragments.as_ref().is_some_and(|p|p.references.is_empty())
}
pub fn reviewed_blank_source_matches(name:&str,raw:&[u8],decoded:&super::sprite::DecodedSprite)->bool{
    use sha2::Digest;
    requires_reviewed_blank(name)&&raw.len()==157993&&sha2::Sha256::digest(raw).as_slice()==ORIGINAL2251_SHA
        &&decoded.frames.len()==21&&decoded.frames.iter().enumerate().all(|(index,f)|{
            if index==0{is_reviewed_blank(name,index,f)}else{f.width>0&&f.height>0
                &&(f.width as usize).checked_mul(f.height as usize).and_then(|n|n.checked_mul(4))==Some(f.rgba.len())}
        })
}
